#include <iostream>

int main() {
    int x = 0, y = 0;
    if (!(std::cin >> x >> y)) return 0;

    // Dangling-else demo: explicit braces matching outer if
    if (y == 8) {
        if (x == 5) {
            std::cout << "MATCH_INNER\n";
        }
    } else {
        std::cout << "MATCH_OUTER_ELSE\n";
    }

    // Correction of Exercise 3.42: evaluate sum increment without modifying temporary
    int corrected_val = (x + y) + 1;
    std::cout << "SumPlusOne: " << corrected_val << "\n";

    return 0;
}

#include <iostream>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 0;
    if (n < 1) n = 1;
    if (n > 20) n = 20;

    // Hollow square of size n
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= n; ++c) {
            if (r == 1 || r == n || c == 1 || c == n) {
                std::cout << '*';
            } else {
                std::cout << ' ';
            }
        }
        std::cout << '\n';
    }

    // Checkerboard 4x4 subset demonstration
    for (int r = 1; r <= 4; ++r) {
        if (r % 2 == 0) {
            std::cout << ' ';
        }
        for (int c = 1; c <= 4; ++c) {
            std::cout << "* ";
        }
        std::cout << '\n';
    }

    return 0;
}

#include <iostream>

int main() {
    int num = 0, bin = 0;
    if (!(std::cin >> num >> bin)) return 0;

    // 5-digit Palindrome test
    int temp = num;
    int d5 = temp % 10; temp /= 10;
    int d4 = temp % 10; temp /= 10;
    int d3 = temp % 10; temp /= 10;
    int d2 = temp % 10; temp /= 10;
    int d1 = temp % 10;

    bool is_palindrome = (d1 == d5 && d2 == d4);
    std::cout << num << (is_palindrome ? " is palindrome\n" : " is not palindrome\n");

    // Count occurrences of digit 7
    int count7 = (d1 == 7) + (d2 == 7) + (d3 == 7) + (d4 == 7) + (d5 == 7);
    std::cout << "Sevens: " << count7 << "\n";

    // Binary to decimal conversion
    int decimal_val = 0;
    int weight = 1;
    while (bin > 0) {
        int bit = bin % 10;
        decimal_val += bit * weight;
        weight *= 2;
        bin /= 10;
    }
    std::cout << "Decimal: " << decimal_val << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    float radius = 0.0f;
    int a = 0, b = 0, c = 0;
    if (!(std::cin >> radius >> a >> b >> c)) return 0;

    const float pi = 3.14159f;
    float diameter = 2.0f * radius;
    float circumference = 2.0f * pi * radius;
    float area = pi * radius * radius;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Circle: D=" << diameter << " C=" << circumference << " A=" << area << "\n";

    // Triangle Inequality and Right Triangle Check
    bool is_tri = (a + b > c) && (a + c > b) && (b + c > a);
    bool is_right = is_tri && ((a * a + b * b == c * c) || (a * a + c * c == b * b) || (b * b + c * c == a * a));
    std::cout << "Triangle: " << (is_tri ? "YES" : "NO") << " Right: " << (is_right ? "YES" : "NO") << "\n";

    // Approximate e with 5 terms: 1 + 1/1! + 1/2! + 1/3! + 1/4!
    double e_approx = 1.0;
    double fact = 1.0;
    for (int i = 1; i <= 4; ++i) {
        fact *= i;
        e_approx += 1.0 / fact;
    }
    std::cout << std::setprecision(4) << "e~" << e_approx << "\n";

    return 0;
}

#include <iostream>

int main() {
    // Input: birth_month birth_day birth_year curr_month curr_day curr_year
    int bm = 0, bd = 0, by = 0;
    int cm = 0, cd = 0, cy = 0;
    if (!(std::cin >> bm >> bd >> by >> cm >> cd >> cy)) return 0;

    int age = cy - by;
    if (cm < bm || (cm == bm && cd < bd)) {
        --age;
    }

    int max_hr = 220 - age;
    int min_target = static_cast<int>(max_hr * 0.50);
    int max_target = static_cast<int>(max_hr * 0.85);

    std::cout << "Age: " << age << "\n";
    std::cout << "MaxHR: " << max_hr << "\n";
    std::cout << "TargetRange: " << min_target << "-" << max_target << "\n";

    // Population 1-year projection demo
    long long pop = 8000000000LL;
    double rate = 0.01;
    long long next_pop = pop + static_cast<long long>(pop * rate);
    std::cout << "NextPop: " << next_pop << "\n";

    return 0;
}

#include <iostream>
#include <utility>

int main() {
    int raw = 0;
    if (!(std::cin >> raw)) return 0;

    // Parse 4 digits (d1 is leftmost)
    int d4 = raw % 10; raw /= 10;
    int d3 = raw % 10; raw /= 10;
    int d2 = raw % 10; raw /= 10;
    int d1 = raw % 10;

    // 1. Substitute
    d1 = (d1 + 7) % 10;
    d2 = (d2 + 7) % 10;
    d3 = (d3 + 7) % 10;
    d4 = (d4 + 7) % 10;

    // 2. Swap 1st with 3rd, 2nd with 4th
    std::swap(d1, d3);
    std::swap(d2, d4);

    // Print encrypted (preserving leading zeros)
    std::cout << "Encrypted: " << d1 << d2 << d3 << d4 << "\n";

    // Decrypt to verify inversion
    std::swap(d1, d3);
    std::swap(d2, d4);
    int orig1 = (d1 + 3) % 10;
    int orig2 = (d2 + 3) % 10;
    int orig3 = (d3 + 3) % 10;
    int orig4 = (d4 + 3) % 10;

    std::cout << "Decrypted: " << orig1 << orig2 << orig3 << orig4 << "\n";
    return 0;
}
